34	/** 270° 仪表弧（起点左下、终点右下），返回 arc 以便复用。 */
35	static lv_obj_t *e_gauge(lv_obj_t *scr, int cx, int cy, int d, int pct)
36	{
37	    lv_obj_t *arc = lv_arc_create(scr);
38	
39	    lv_obj_set_size(arc, d, d);
40	    lv_obj_set_pos(arc, cx - d / 2, cy - d / 2);
41	    lv_obj_remove_flag(arc, LV_OBJ_FLAG_CLICKABLE);
42	    lv_obj_remove_flag(arc, LV_OBJ_FLAG_SCROLLABLE);
43	    lv_obj_set_style_pad_all(arc, 0, 0);
44	    lv_obj_set_style_bg_opa(arc, LV_OPA_TRANSP, 0);
45	    lv_obj_set_style_border_width(arc, 0, 0);
46	    lv_obj_set_style_outline_width(arc, 0, 0);
47	    lv_obj_set_style_shadow_width(arc, 0, 0);
48	    lv_obj_set_style_arc_width(arc, 8, LV_PART_MAIN);
49	    lv_obj_set_style_arc_color(arc, lv_color_hex(E_TRACK), LV_PART_MAIN);
50	    lv_obj_set_style_arc_rounded(arc, true, LV_PART_MAIN);
51	    lv_obj_set_style_arc_width(arc, 8, LV_PART_INDICATOR);
52	    lv_obj_set_style_arc_color(arc, lv_color_hex(E_ACC), LV_PART_INDICATOR);
53	    lv_obj_set_style_arc_rounded(arc, true, LV_PART_INDICATOR);
54	    lv_obj_set_style_bg_opa(arc, LV_OPA_TRANSP, LV_PART_KNOB);
55	    lv_obj_set_style_border_width(arc, 0, LV_PART_KNOB);
56	    lv_obj_set_style_pad_all(arc, 0, LV_PART_KNOB);
57	    lv_arc_set_bg_angles(arc, 0, 270);
58	    lv_arc_set_rotation(arc, 135);
59	    lv_arc_set_range(arc, 0, 100);
60	    lv_arc_set_value(arc, pct);
61	    return arc;
62	}
