15	int d2_screen_from_env(void)
16	{
17	    const char *s = getenv("SIM_DESIGN_SCREEN");
18	
19	    if (!s || !s[0]) {
20	        return D2_SCREEN_MAIN;
21	    }
22	    if (strcmp(s, "ride") == 0 || strcmp(s, "1") == 0) {
23	        return D2_SCREEN_RIDE;
24	    }
25	    if (strcmp(s, "nav") == 0 || strcmp(s, "2") == 0) {
26	        return D2_SCREEN_NAV;
27	    }
28	    if (strcmp(s, "menu") == 0 || strcmp(s, "3") == 0) {
29	        return D2_SCREEN_MENU;
30	    }
31	    if (strcmp(s, "main") != 0 && strcmp(s, "0") != 0) {
32	        fprintf(stderr,
33	                "sim: unknown SIM_DESIGN_SCREEN=%s (main|ride|nav|menu)\n", s);
34	    }
35	    return D2_SCREEN_MAIN;
36	}
