38	static void (*s_d2_build)(lv_obj_t *, int);
39	static lv_obj_t *s_d2_scr;
40	
41	static int d2_count_objs(lv_obj_t *o)
42	{
43	    int n = 1;
44	    const uint32_t c = lv_obj_get_child_count(o);
45	
46	    for (uint32_t i = 0; i < c; i++) {
47	        n += d2_count_objs(lv_obj_get_child(o, (int32_t)i));
48	    }
49	    return n;
50	}
51	
52	static void d2_build_now(int screen)
53	{
54	    lv_obj_clean(s_d2_scr);
55	    s_d2_build(s_d2_scr, screen);
56	    printf("design2: screen=%d objects=%d\n", screen,
57	           d2_count_objs(s_d2_scr));
58	    fflush(stdout);
59	}
