61	static void d2_key_timer(lv_timer_t *t)
62	{
63	    (void)t;
64	    for (;;) {
65	        int k = sim_display_take_raw_key();
66	
67	        if (k == 0) {
68	            break;
69	        }
70	        if (k >= '1' && k <= '4' && s_d2_scr && s_d2_build) {
71	            d2_build_now(k - '1');
72	        }
73	    }
74	}
75	
76	void d2_scene_start(lv_obj_t *scr, design_build_fn_t build)
77	{
78	    s_d2_scr = scr;
79	    s_d2_build = build;
80	    d2_build_now(d2_screen_from_env());
81	    lv_timer_create(d2_key_timer, 60, NULL);
82	}
