85	
86	lv_obj_t *d2_ring(lv_obj_t *p, int cx, int cy, int d, int thickness,
87	                  uint32_t hex)
88	{
89	    lv_obj_t *o = d_box(p, cx - d / 2, cy - d / 2, d, d, 0x000000u,
90	                        LV_OPA_TRANSP, d / 2);
91	
92	    lv_obj_set_style_border_width(o, thickness, 0);
93	    lv_obj_set_style_border_color(o, lv_color_hex(hex), 0);
94	    lv_obj_set_style_border_opa(o, LV_OPA_COVER, 0);
95	    return o;
96	}
97	
98	lv_obj_t *d2_disc(lv_obj_t *p, int cx, int cy, int d, uint32_t hex)
99	{
100	    return d_box(p, cx - d / 2, cy - d / 2, d, d, hex, LV_OPA_COVER, d / 2);
101	}
102	
103	lv_obj_t *d2_arc(lv_obj_t *p, int cx, int cy, int d, int thickness,
104	                 int start, int span, uint32_t hex)
105	{
106	    lv_obj_t *arc = lv_arc_create(p);
107	
108	    lv_obj_set_size(arc, d, d);
109	    lv_obj_set_pos(arc, cx - d / 2, cy - d / 2);
110	    lv_obj_remove_flag(arc, LV_OBJ_FLAG_CLICKABLE);
111	    lv_obj_remove_flag(arc, LV_OBJ_FLAG_SCROLLABLE);
112	    lv_obj_set_style_pad_all(arc, 0, 0);
113	    lv_obj_set_style_bg_opa(arc, LV_OPA_TRANSP, 0);
114	    lv_obj_set_style_border_width(arc, 0, 0);
115	    lv_obj_set_style_outline_width(arc, 0, 0);
116	    lv_obj_set_style_shadow_width(arc, 0, 0);
117	
118	    /* 主弧不画，只留 indicator 扇段。 */
119	    lv_obj_set_style_arc_opa(arc, LV_OPA_TRANSP, LV_PART_MAIN);
120	    lv_obj_set_style_arc_width(arc, 0, LV_PART_MAIN);
121	    lv_obj_set_style_arc_rounded(arc, false, LV_PART_MAIN);
122	
123	    lv_obj_set_style_arc_opa(arc, LV_OPA_COVER, LV_PART_INDICATOR);
124	    lv_obj_set_style_arc_width(arc, thickness, LV_PART_INDICATOR);
125	    lv_obj_set_style_arc_color(arc, lv_color_hex(hex), LV_PART_INDICATOR);
126	    lv_obj_set_style_arc_rounded(arc, true, LV_PART_INDICATOR);
127	
128	    lv_obj_set_style_bg_opa(arc, LV_OPA_TRANSP, LV_PART_KNOB);
129	    lv_obj_set_style_border_width(arc, 0, LV_PART_KNOB);
130	    lv_obj_set_style_pad_all(arc, 0, LV_PART_KNOB);
131	
132	    lv_arc_set_bg_angles(arc, start, start + span);
133	    lv_arc_set_rotation(arc, 0);
134	    lv_arc_set_range(arc, 0, 100);
135	    lv_arc_set_value(arc, 100);
136	    return arc;
