1	/**
2	 * @file scene_vmap.c
3	 * @brief vmap 底图 mock：直接用 RGB565 光栅化 + LVGL 画字。
4	 *
5	 * 这不是最终渲染器，而是"调色板/线宽/字号在 1× 下到底好不好看"的试验台：
6	 * 几何用 vmap_raster.c（和板端 vmap_render.c 同路子：扫描线填充 + 四边形粗线），
7	 * 文字走 lv_canvas 的 draw layer（板端 vmap_label.c 也是往同一块 canvas 上画）。
8	 *
9	 * 调色板数值和 HTML 预览的 paper 预设一一对应，两边改要一起改。
10	 */
11	
12	#include <math.h>
13	#include <string.h>
14	
15	#include "sim.h"
16	#include "vmap_raster.h"
17	
18	/* ── 调色板（= vmap_style.js 的 paper 预设，改一边要改另一边） ───── */
19	#define C_BG        0xF4F1E8
20	#define C_PARK      0xD8E8CA
21	#define C_FOREST    0xCBE0BC
22	#define C_WATER     0xA9D0E8
23	#define C_WATER_EDGE 0x7FB6D4
24	#define C_CASE_MAJ  0xC6A054
25	#define C_FILL_MAJ  0xFBDC9C
26	#define C_CASE_MID  0xB7B0A1
27	#define C_FILL_MID  0xFEFDF9
28	#define C_CASE_MIN  0xCAC4B6
29	#define C_PATH      0xA97C4A
30	#define C_TRACK     0xE0503A
31	#define C_LBL_ROAD  0x514C45
32	#define C_LBL_WATER 0x3D7EA6
33	#define C_LBL_PARK  0x3F7048
34	
35	static uint16_t *s_buf;
36	
37	static inline uint16_t hex565(uint32_t rgb)
38	{
39	    return vr_rgb565((uint8_t)(rgb >> 16), (uint8_t)(rgb >> 8), (uint8_t)rgb);
40	}
41	
42	/* 虚线：按弧长切"实/虚"子段，再交给 vr_line。
43	 * 不能按 1px 递进画 —— 那么短的段会被线宽撑成锯齿。 */
44	static void dashed_line(vr_canvas_t *c, const int32_t *xy, int n, int width,
45	                        uint16_t color, int on, int off)
46	{
47	    const int period = on + off;
48	    int phase = 0;
49	
50	    for (int i = 0; i + 1 < n; i++) {
51	        const double ax = (double)xy[2 * i];
52	        const double ay = (double)xy[2 * i + 1];
53	        const double bx = (double)xy[2 * i + 2];
54	        const double by = (double)xy[2 * i + 3];
55	        const double dx = bx - ax;
56	        const double dy = by - ay;
57	        const int len = (int)(0.5 + sqrt(dx * dx + dy * dy));
58	        int t = 0;
59	
60	        while (t < len) {
61	            const int in_phase = phase % period;
62	            const int in_dash = in_phase < on;
63	            const int left = in_dash ? (on - in_phase) : (period - in_phase);
64	            int step = left;
65	
66	            if (step > len - t) {
67	                step = len - t;
68	            }
69	            if (in_dash) {
70	                int32_t seg[4];
71	                seg[0] = (int32_t)(ax + dx * t / len);
72	                seg[1] = (int32_t)(ay + dy * t / len);
73	                seg[2] = (int32_t)(ax + dx * (t + step) / len);
74	                seg[3] = (int32_t)(ay + dy * (t + step) / len);
75	                vr_line(c, seg, 2, width, color);
76	            }
77	            t += step;
78	            phase += step;
79	        }
80	    }
81	}
82	
83	static void canvas_label(lv_obj_t *canvas, lv_layer_t *layer, int x, int y, int w,
84	                         const char *txt, uint32_t color, int px, bool italic,
85	                         bool centered)
86	{
87	    lv_draw_label_dsc_t dsc;
88	
89	    lv_draw_label_dsc_init(&dsc);
90	    dsc.text = txt;
91	    dsc.font = sim_font_cjk_style(px, italic);
92	    dsc.color = lv_color_hex(color);
93	    dsc.align = centered ? LV_TEXT_ALIGN_CENTER : LV_TEXT_ALIGN_LEFT;
94	    dsc.letter_space = 0;
95	    /* 白描边：地图文字必须有 halo，否则压在路/水上读不出来 */
96	    dsc.outline_stroke_color = lv_color_hex(0xFFFFFF);
97	    dsc.outline_stroke_width = 3;
98	    dsc.outline_stroke_opa = LV_OPA_90;
99	    (void)italic;
100	
101	    lv_area_t a;
102	    a.x1 = x;
103	    a.y1 = y;
104	    a.x2 = x + w - 1;
105	    a.y2 = y + px * 2;
106	    lv_draw_label(layer, &dsc, &a);
107	}
108	
109	void scene_vmap_create(lv_obj_t *scr, const sim_cfg_t *cfg)
110	{
111	    const int W = cfg->width;
112	    const int H = cfg->height;
113	
114	    lv_obj_set_style_bg_color(scr, lv_color_hex(C_BG), 0);
115	    lv_obj_set_style_bg_opa(scr, LV_OPA_COVER, 0);
116	    lv_obj_remove_flag(scr, LV_OBJ_FLAG_SCROLLABLE);
117	
118	    s_buf = lv_malloc((size_t)W * (size_t)H * 2u);
119	    if (!s_buf) {
120	        return;
121	    }
122	
123	    lv_obj_t *canvas = lv_canvas_create(scr);
124	    lv_obj_set_pos(canvas, 0, 0);
125	    lv_canvas_set_buffer(canvas, s_buf, W, H, LV_COLOR_FORMAT_RGB565);
126	
127	    vr_canvas_t c = { .px = s_buf, .w = W, .h = H };
128	
129	    /* 1) 底色 + 绿地 */
130	    vr_fill(&c, hex565(C_BG));
131	
132	    int32_t forest[] = { 0, 300, 90, 268, 132, 300, 96, 400, 0, 400 };
133	    vr_poly(&c, forest, 5, hex565(C_FOREST));
134	
135	    int32_t park[] = { 150, 250, 232, 268, 240, 340, 168, 352, 140, 300 };
136	    vr_poly(&c, park, 5, hex565(C_PARK));
137	
138	    /* 2) 水面：填色 + 一圈稍深的边 */
139	    int32_t lake[] = { 138, 26, 196, 18, 226, 52, 214, 96, 166, 104, 140, 70 };
140	    vr_poly(&c, lake, 6, hex565(C_WATER));
141	    {
142	        int32_t edge[14];
143	        memcpy(edge, lake, sizeof(lake));
144	        edge[12] = lake[0];
145	        edge[13] = lake[1];
146	        vr_line(&c, edge, 7, 1, hex565(C_WATER_EDGE));
147	    }
148	
149	    /* 3) 支路网格：白芯 + 浅灰壳 */
150	    static const int32_t grid[][4] = {
151	        { 0, 150, 240, 158 }, { 0, 236, 240, 244 },
152	        { 52, 0, 58, 400 },   { 104, 0, 110, 400 },
153	        { 186, 0, 192, 400 }, { 228, 0, 232, 400 },
154	    };
155	    for (size_t i = 0; i < sizeof(grid) / sizeof(grid[0]); i++) {
156	        vr_line(&c, grid[i], 2, 4, hex565(C_CASE_MIN));
157	    }
158	    for (size_t i = 0; i < sizeof(grid) / sizeof(grid[0]); i++) {
159	        vr_line(&c, grid[i], 2, 2, hex565(C_FILL_MID));
160	    }
161	
162	    /* 4) 次干道（横向） */
163	    int32_t mid[] = { 0, 196, 240, 204 };
164	    vr_line(&c, mid, 2, 5, hex565(C_CASE_MID));
165	    vr_line(&c, mid, 2, 3, hex565(C_FILL_MID));
166	
167	    /* 5) 主干道（斜穿） */
168	    int32_t major[] = { -10, 372, 70, 330, 150, 292, 250, 250 };
169	    vr_line(&c, major, 4, 7, hex565(C_CASE_MAJ));
170	    vr_line(&c, major, 4, 4, hex565(C_FILL_MAJ));
171	
172	    /* 6) 步道（虚线） */
173	    int32_t path[] = { 24, 60, 60, 140, 96, 208, 128, 286 };
174	    dashed_line(&c, path, 4, 2, hex565(C_PATH), 5, 4);
175	
176	    /* 7) 骑行轨迹 + 当前位置（白壳只为在深色路面上拉出对比，比芯细一点） */
177	    int32_t track[] = { 30, 340, 62, 300, 96, 262, 118, 214, 150, 186, 190, 168 };
178	    vr_line(&c, track, 6, 4, hex565(0xFFFFFF));
179	    vr_line(&c, track, 6, 2, hex565(C_TRACK));
180	    vr_disc(&c, 190, 168, 6, hex565(0xFFFFFF));
181	    vr_disc(&c, 190, 168, 4, hex565(0x1D6FD0));
182	
183	    /* 8) 文字：和板端一样画在同一块 canvas 上 */
184	    lv_layer_t layer;
185	    lv_canvas_init_layer(canvas, &layer);
186	    canvas_label(canvas, &layer, 84, 176, 72, "清流路", C_LBL_ROAD, 11, false, true);
187	    canvas_label(canvas, &layer, 160, 44, 64, "东升湖", C_LBL_WATER, 11, true, true);
188	    canvas_label(canvas, &layer, 160, 300, 72, "中央公园", C_LBL_PARK, 11, false, true);
189	    canvas_label(canvas, &layer, 44, 300, 64, "扬子大道", C_LBL_ROAD, 10, false, false);
190	    lv_canvas_finish_layer(canvas, &layer);
191	
192	    /* 9) 角标：说明这块是什么（真机上不会有） */
193	    lv_obj_t *badge = lv_label_create(scr);
194	    lv_label_set_text(badge, "vmap mock  z14  1x");
195	    lv_obj_set_style_text_font(badge, &lv_font_montserrat_12, 0);
196	    lv_obj_set_style_text_color(badge, lv_color_hex(0x6B675E), 0);
197	    lv_obj_set_style_bg_color(badge, lv_color_hex(0xFFFFFF), 0);
198	    lv_obj_set_style_bg_opa(badge, LV_OPA_70, 0);
199	    lv_obj_set_style_pad_hor(badge, 6, 0);
200	    lv_obj_set_style_pad_ver(badge, 3, 0);
201	    lv_obj_set_style_radius(badge, 6, 0);
202	    lv_obj_align(badge, LV_ALIGN_TOP_LEFT, 6, 6);
203	}
