1	/**
2	 * @file vmap_raster.h
3	 * @brief 极简 RGB565 光栅化（矩形 / 多边形 / 粗线 / 圆）。
4	 *
5	 * 这个文件是**给 MCU 端 vmap 做参考实现**用的：不依赖 LVGL 的 draw 层，
6	 * 直接往 canvas 的 RGB565 缓冲里写像素 —— 和板子上 vmap_render.c 的路子
7	 * 一样。模拟器里先用它画 mock 地图，验证调色板、线宽、字号在 1× 下的观感。
8	 */
9	
10	#ifndef VMAP_RASTER_H
11	#define VMAP_RASTER_H
12	
13	#include <stdint.h>
14	
15	#ifdef __cplusplus
16	extern "C" {
17	#endif
18	
19	/** RGB888 → RGB565，和 vmap_style.h 的 VMAP_STYLE_RGB565 同一算法。 */
20	static inline uint16_t vr_rgb565(uint8_t r, uint8_t g, uint8_t b)
21	{
22	    return (uint16_t)((((uint16_t)r & 0xF8u) << 8) |
23	                      (((uint16_t)g & 0xFCu) << 3) |
24	                      ((uint16_t)b >> 3));
25	}
26	
27	typedef struct {
28	    uint16_t *px;
29	    int w;
30	    int h;
31	} vr_canvas_t;
32	
33	void vr_fill(vr_canvas_t *c, uint16_t color);
34	void vr_rect(vr_canvas_t *c, int x0, int y0, int x1, int y1, uint16_t color);
35	void vr_poly(vr_canvas_t *c, const int32_t *xy, int n, uint16_t color);
36	void vr_line(vr_canvas_t *c, const int32_t *xy, int n, int width, uint16_t color);
37	void vr_disc(vr_canvas_t *c, int cx, int cy, int r, uint16_t color);
38	
39	#ifdef __cplusplus
40	}
41	#endif
42	
43	#endif /* VMAP_RASTER_H */
