290	
291	        if (tour) {
292	            frames = 6000;
293	        }
294	#endif
295	        for (int i = 0; i < frames; i++) {
296	            s_vtick += 16;
297	            lv_timer_handler();
298	#ifdef SIM_WITH_UI
299	            if (tour && sim_ui_tour_done()) {
300	                break;
301	            }
302	            /* WP-FADE/R1 临时探针跑完即退出（未启用时恒为 false）。 */
303	            if (sim_ui_fade_probe_done()) {
304	                break;
305	            }
306	#endif
307	        }
308	        if (cfg.shot) {
309	            int w = 0;
310	            int h = 0;
311	            const uint16_t *fb = sim_display_shadow(&w, &h);
312	
313	            if (!sim_png_write(cfg.shot, fb, w, h)) {
314	                fprintf(stderr, "failed to write png\n");
315	                sim_display_shutdown();
