323	
324	#ifdef SIM_WITH_UI
325	            if (sim_ui_tour_enabled() && sim_ui_tour_done()) {
326	                break;
327	            }
328	#endif
329	            if (idle < 1) {
330	                idle = 1;
331	            }
332	            if (idle > 16) {
333	                idle = 16;
334	            }
335	            usleep(idle * 1000);
336	        }
337	    }
338	
339	    sim_display_shutdown();
340	    return 0;
341	}
