24	static const char *cjk_font_path(void)
25	{
26	    const char *env = getenv("SIM_CJK_FONT");
27	
28	    if (env && env[0]) {
29	        return env;
30	    }
31	    /* 用**码表固件里那份** TTF（MiSans-Medium 子集），字形与板端一致。
32	     * 设备路径是 /mnt/fat/fonts/MiSans-Medium.subset.ttf。 */
33	    return "/home/jinsc/SDK/vela/openvela/vendor/my_vendor/boards/sf32lb52/my_vendor/mkfs/fat/fonts/MiSans-Medium.subset.ttf";
34	}
35	
36	lv_font_t *sim_font_cjk_style(int px, bool italic)
37	{
38	    if (px < 6) {
39	        px = 6;
40	    }
41	    for (int i = 0; i < s_cache_n; i++) {
42	        if (s_cache[i].px == px && s_cache[i].italic == italic) {
43	            return s_cache[i].font;
44	        }
45	    }
46	
47	    lv_font_t *font = lv_freetype_font_create(cjk_font_path(),
48	                                              LV_FREETYPE_FONT_RENDER_MODE_BITMAP,
49	                                              (uint32_t)px,
50	                                              italic ? LV_FREETYPE_FONT_STYLE_ITALIC
51	                                                     : LV_FREETYPE_FONT_STYLE_NORMAL);
52	    if (!font) {
53	        fprintf(stderr, "sim: cannot load CJK font %s, using built-in subset\n",
54	                cjk_font_path());
55	        font = (lv_font_t *)&lv_font_source_han_sans_sc_16_cjk;
56	    }
57	
58	    if (s_cache_n < SIM_FONT_CACHE) {
59	        s_cache[s_cache_n].px = px;
60	        s_cache[s_cache_n].italic = italic;
61	        s_cache[s_cache_n].font = font;
62	        s_cache_n++;
63	    }
64	    return font;
65	}
66	
67	lv_font_t *sim_font_cjk(int px)
68	{
69	    return sim_font_cjk_style(px, false);
70	}
