/**
 * @file scene_vmap_live.c
 * @brief `--scene vmap`：**真 vmap 组件**（vendor 的 vmap_view_t）+ 交互 + HUD。
 *
 * 与 `src/scene_vmap.c`（mock 底图，注册为 `vmap-mock`）不同，这里读设备真正
 * 烧的 z14 网格包（`mkfs/fat/map`，经 `/tmp/vmap` 短路径），走 vmap_view 的
 * 瓦片泵 —— 与板端地图页同一份光栅化代码。
 *
 * 本场景是 WP-VMAPAPI/R1 的取证台：
 *   - 运行时 viewport 尺寸        `--vmap-viewport WxH`（组件 set_viewport）
 *   - 运行时中心图标              `--vmap-icon dev|alt|none`（set_center_icon）
 *   - 运行时中心点                `--vmap-center LON,LAT`（center_on）
 *   - 拖动                       鼠标拖动 / `--vmap-pan DX,DY`（pan_begin/px/end）
 *   - 连续缩放                   滚轮 / `+` `-` / `--vmap-scale S`（set_scale）
 *
 * HUD 显示 lon/lat/scale/viewport/中心图标，便于截图直接读参数。
 */

#include <math.h>
#include <stdio.h>
#include <string.h>
#include <sys/stat.h>
#include <unistd.h>

#include "sim.h"
#include "sim_config.h"

#include "NaviArrow.h"
#include "vmap_config.h"
#include "vmap_tile_system.h"
#include "vmap_view.h"

#define LIVE_SCREEN_BG   0x121417
#define LIVE_MAP_BG      0xEFE9DA
#define LIVE_FRAME_COLOR 0xFF4D4D
#define LIVE_WHEEL_STEP  1.15

typedef struct {
    lv_obj_t * scr;
    lv_obj_t * holder;
    lv_obj_t * frame;
    lv_obj_t * overlay;
    lv_obj_t * hud;
    lv_obj_t * hud_label;
    vmap_view_t * view;
    lv_timer_t * timer;

    int vw;
    int vh;
    int screen_w;
    int screen_h;
    int hud_h;

    /* 启动参数（也是 r 键的复位目标） */
    double boot_lon;
    double boot_lat;
    double boot_scale;
    int boot_icon;

    double lon;
    double lat;
    double scale;
    int zoom;
    int icon;

    bool follow;

    bool pan_pending;    /**< 脚本化平移还没执行 */
    bool pan_applied;
    int pan_dx;
    int pan_dy;
    int drag_px;         /**< 累计拖动（设备像素，右/下为正；复位/回中时清零） */
    int drag_py;

    /* 运行时改 viewport 尺寸（`--vmap-resize WxH`）：首帧后调组件 API。 */
    bool resize_pending;
    bool resize_applied;
    int resize_w;
    int resize_h;

    /* 脚本化能力验证（都等首帧 + 泵空闲，每次只推进一步）：
     *   zoom_at ×N → drag ×N。pan（单次）走原来的 pan_pending。 */
    int za_idx;
    int za_n;
    int za_x[2];
    int za_y[2];
    double za_f[2];
    bool za_done;

    int drag_left;
    int drag_n;
    int drag_dx;
    int drag_dy;
    int drag_step_x;
    int drag_step_y;
    int32_t drag_x0;
    int32_t drag_y0;
    bool drag_started;
    bool drag_done;

    bool heading;
    double course;

    /* 运行时换图（只调组件 API；不碰 update_arrow ⇒ 考验组件自己保朝向）。 */
    int swap_n;
    int swap_idx;
    int swap_icon[3];

    bool recenter_pending;

    /* 跟车：喂 GNSS 点 */
    int follow_left;
    int follow_n;
    double follow_m;
    double follow_km_per_deg;
    double follow_lon0;

    double pending_scale; /**< 泵忙时先记账的缩放（0 = 无） */

    /* `alt` 中心图标：运行时生成的 ARGB8888 准星（不依赖板端资源） */
    lv_image_dsc_t alt_dsc;
    uint8_t * alt_px;
} live_t;

static live_t s;

/* ─────────────────────────────────────────────────────────────────────────
 * 中心图标
 * ──────────────────────────────────────────────────────────────────────── */

static const char * icon_name(int icon)
{
    switch (icon) {
        case SIM_VMAP_ICON_ALT:  return "crosshair";
        case SIM_VMAP_ICON_NONE: return "none";
        default:                 return "dev-arrow";
    }
}

/**
 * @brief 运行时画一枚 36x36 的蓝色准星（ARGB8888）。
 *
 * 板端两枚箭头都是编译进 flash 的位图；模拟器要验证"可换图"，再带一张
 * 完全不同的图最直观，也避免依赖 PNG 解码器。
 */
static void alt_icon_build(void)
{
    enum { W = 36, H = 36 };

    s.alt_px = (uint8_t *)lv_malloc((size_t)W * H * 4u);
    if (s.alt_px == NULL) {
        return;
    }
    memset(s.alt_px, 0, (size_t)W * H * 4u);

    for (int y = 0; y < H; y++) {
        for (int x = 0; x < W; x++) {
            const double dx = (double)x - (W - 1) / 2.0;
            const double dy = (double)y - (H - 1) / 2.0;
            const double r = sqrt(dx * dx + dy * dy);
            uint32_t argb = 0u;

            if (r >= 14.5 && r <= 16.5) {
                argb = 0xFF1D6FD0u;                  /* 外圈：蓝 */
            } else if (r >= 12.0 && r <= 13.0) {
                argb = 0xFFFFFFFFu;                  /* 内圈：白 */
            } else if (r <= 3.2) {
                argb = 0xFF1D6FD0u;                  /* 中心点 */
            } else if ((fabs(dx) <= 1.0 && fabs(dy) >= 9.0 && fabs(dy) <= 16.5)
                || (fabs(dy) <= 1.0 && fabs(dx) >= 9.0 && fabs(dx) <= 16.5)) {
                argb = 0xFF1D6FD0u;                  /* 四个方向的刻度 */
            }

            if (argb != 0u) {
                uint8_t * p = s.alt_px + ((size_t)y * W + (size_t)x) * 4u;

                p[0] = (uint8_t)(argb & 0xFFu);        /* B */
                p[1] = (uint8_t)((argb >> 8) & 0xFFu); /* G */
                p[2] = (uint8_t)((argb >> 16) & 0xFFu);/* R */
                p[3] = (uint8_t)((argb >> 24) & 0xFFu);/* A */
            }
        }
    }

    memset(&s.alt_dsc, 0, sizeof(s.alt_dsc));
    s.alt_dsc.header.magic = LV_IMAGE_HEADER_MAGIC;
    s.alt_dsc.header.cf = LV_COLOR_FORMAT_ARGB8888;
    s.alt_dsc.header.w = W;
    s.alt_dsc.header.h = H;
    s.alt_dsc.header.stride = W * 4;
    s.alt_dsc.data_size = W * H * 4u;
    s.alt_dsc.data = s.alt_px;
}

