void scene_vmap_live_create(lv_obj_t * scr, const sim_cfg_t * cfg)
{
    const int sw = cfg->width;
    const int sh = cfg->height;
    const int hud_h = 4 * 16 + 10;
    int32_t cx = 0;
    int32_t cy = 0;
    int zoom;

    memset(&s, 0, sizeof(s));
    s.scr = scr;
    s.screen_w = sw;
    s.screen_h = sh;
    s.hud_h = hud_h;

    map_path_hint();

    /* ── 尺寸与中心：参数优先，缺省用屏幕/板端开机中心 ─────────────── */
    s.vw = cfg->vmap_w > 0 ? cfg->vmap_w : sw;
    s.vh = cfg->vmap_h > 0 ? cfg->vmap_h : sh;
    if (s.vw > sw || s.vh > sh) {
        fprintf(stderr, "vmap: viewport %dx%d 超出屏幕 %dx%d（用 --size 放大屏幕）\n",
            s.vw, s.vh, sw, sh);
        if (s.vw > sw) {
            s.vw = sw;
        }
        if (s.vh > sh) {
            s.vh = sh;
        }
    }
    zoom = cfg->vmap_zoom > 0 ? cfg->vmap_zoom : VMAP_DEFAULT_ZOOM;
    s.zoom = zoom;
    s.scale = cfg->vmap_scale > 0.0 ? cfg->vmap_scale : VMAP_DEFAULT_SCALE;
    s.icon = cfg->vmap_icon;

    if (isfinite(cfg->vmap_lon) && isfinite(cfg->vmap_lat)) {
        s.lon = cfg->vmap_lon;
        s.lat = cfg->vmap_lat;
    } else {
        vmap_boot_lonlat(&s.lon, &s.lat);
    }
    s.boot_lon = s.lon;
    s.boot_lat = s.lat;
    s.boot_scale = s.scale;
    s.boot_icon = s.icon;
    s.follow = true;

    s.pan_pending = cfg->vmap_pan_set;
    s.pan_dx = cfg->vmap_pan_x;
    s.pan_dy = cfg->vmap_pan_y;

    s.resize_pending = cfg->vmap_rw > 0 && cfg->vmap_rh > 0;
    s.resize_w = cfg->vmap_rw;
    s.resize_h = cfg->vmap_rh;

    s.za_n = cfg->vmap_zoom_at_n;
    for (int i = 0; i < s.za_n && i < 2; i++) {
        s.za_x[i] = cfg->vmap_za_x[i];
        s.za_y[i] = cfg->vmap_za_y[i];
        s.za_f[i] = cfg->vmap_za_f[i];
    }
    s.drag_n = cfg->vmap_drag_n;
    s.drag_left = cfg->vmap_drag_n;
    s.drag_step_x = cfg->vmap_drag_x;
    s.drag_step_y = cfg->vmap_drag_y;
    s.heading = cfg->vmap_heading;
    s.course = cfg->vmap_course;
    s.recenter_pending = cfg->vmap_recenter;
    s.follow_n = cfg->vmap_follow_n;
    s.follow_left = cfg->vmap_follow_n;
    s.follow_m = cfg->vmap_follow_m;
    s.follow_lon0 = s.lon;
    s.swap_n = cfg->vmap_swap_n;
    for (int i = 0; i < s.swap_n && i < 3; i++) {
        s.swap_icon[i] = cfg->vmap_swap_icon[i];
    }

    /* ── 屏幕 / 视口容器 ──────────────────────────────────────────── */
    lv_obj_set_style_bg_color(scr, lv_color_hex(LIVE_SCREEN_BG), 0);
    lv_obj_set_style_bg_opa(scr, LV_OPA_COVER, 0);
    lv_obj_remove_flag(scr, LV_OBJ_FLAG_SCROLLABLE);

    s.holder = lv_obj_create(scr);
    lv_obj_remove_style_all(s.holder);
    lv_obj_set_size(s.holder, s.vw, s.vh);
    lv_obj_set_pos(s.holder, 0, 0);
    lv_obj_set_style_bg_color(s.holder, lv_color_hex(LIVE_MAP_BG), 0);
    lv_obj_set_style_bg_opa(s.holder, LV_OPA_COVER, 0);
    lv_obj_remove_flag(s.holder, LV_OBJ_FLAG_SCROLLABLE);
    lv_obj_remove_flag(s.holder, LV_OBJ_FLAG_OVERFLOW_VISIBLE);

    /* 红框 = 视口边界（只用于肉眼核对裁切/居中，不是地图的一部分）。 */
    {
        lv_obj_t * frame = lv_obj_create(scr);

        s.frame = frame;
        lv_obj_remove_style_all(frame);
        lv_obj_set_size(frame, s.vw + 2, s.vh + 2);
        lv_obj_set_pos(frame, -1, -1);
        lv_obj_set_style_bg_opa(frame, LV_OPA_TRANSP, 0);
        lv_obj_set_style_border_width(frame, 2, 0);
        lv_obj_set_style_border_color(frame, lv_color_hex(LIVE_FRAME_COLOR), 0);
        lv_obj_set_style_border_opa(frame, LV_OPA_80, 0);
        lv_obj_remove_flag(frame, LV_OBJ_FLAG_CLICKABLE);
    }

    /* ── 真 vmap 组件（与板端地图页同一份实现） ───────────────────── */
    s.view = vmap_view_create(s.holder, s.vw, s.vh, VMAP_CANVAS_MARGIN);
    if (s.view == NULL) {
        fprintf(stderr, "vmap: vmap_view_create failed (%dx%d)\n", s.vw, s.vh);
        return;
    }

    vmap_view_bind_arrow_layer(s.view, s.holder);
    vmap_view_set_follow_mode(s.view, true);
    vmap_view_set_font(s.view, sim_font_cjk(15));

    alt_icon_build();
    vmap_view_set_center_icon(s.view, icon_src(s.icon));

    /* center_on = 直接定位（同时把跟车点设到这里，f 键恢复跟随时回中）。 */
    vmap_view_set_view(s.view, s.lon, s.lat, zoom);
    vmap_view_center_on(s.view, s.lon, s.lat);
    vmap_view_set_scale(s.view, s.scale);
    /* 航向朝上：首帧之前打开，render_finish() 才会把整幅 C 烘进 R。 */
    if (s.heading) {
        vmap_view_set_heading_up(s.view, true);
        vmap_view_set_heading(s.view, (float)s.course, 20.0f);
    }
    vmap_view_update_arrow(s.view, s.lon, s.lat, (float)s.course);
    vmap_view_render(s.view);

    /* ── 拖动面：透明覆盖层吃指针事件（滚轮/按键走 sim_display 通道） ── */
    s.overlay = lv_obj_create(s.holder);
    lv_obj_remove_style_all(s.overlay);
    lv_obj_set_size(s.overlay, s.vw, s.vh);
    lv_obj_set_pos(s.overlay, 0, 0);
    lv_obj_set_style_bg_opa(s.overlay, LV_OPA_TRANSP, 0);
    lv_obj_add_flag(s.overlay, LV_OBJ_FLAG_CLICKABLE);
    lv_obj_add_event_cb(s.overlay, drag_cb, LV_EVENT_ALL, NULL);

    /* ── HUD ──────────────────────────────────────────────────────── */
    s.hud = lv_obj_create(scr);
    lv_obj_remove_style_all(s.hud);
    lv_obj_set_height(s.hud, hud_h);
    lv_obj_set_style_bg_color(s.hud, lv_color_hex(0x000000), 0);
    lv_obj_set_style_bg_opa(s.hud, LV_OPA_70, 0);
    lv_obj_set_style_pad_all(s.hud, 3, 0);
    lv_obj_remove_flag(s.hud, LV_OBJ_FLAG_SCROLLABLE);
    lv_obj_add_flag(s.hud, LV_OBJ_FLAG_IGNORE_LAYOUT);
    hud_place();
    if (!cfg->vmap_hud) {
        lv_obj_add_flag(s.hud, LV_OBJ_FLAG_HIDDEN);
    }

