 * @file scene_design_e.c
 * @brief WP-DESIGN3/R1 方案 E「模式盘 Dial」完整设计：Helm 版。
 *
 * 视觉主线：一枚 160px 的舵轮。外圈 24 格细刻度 + 4 根主刻度，选中扇区用
 * 浅色填充 + 深色边（不发光），盘心是一块纸色轮毂，轮毂里放模式名/描述/关键
 * 数字；指针是一根从轮毂边缘伸向扇区的舵柄，末端一短横。
 *
 * 十屏由 SIM_DESIGN_SCREEN 选：
 *   main | rotate | longpress | ride | nav | record | settings | display |
 *   sensor | about（也接受 0..9；窗口模式按 1..9 / 0 直接切屏）。
 *
 * 导航页接**真 vmap 组件**（SIM_WITH_UI=ON 时，和 `--scene vmap` 同一份
 * vmap_view + 设备瓦片）；未编 UI 时退回一张同色板的示意地图（会打印提示）。
 *
 * 仅模拟器出图，不链接进板端。
 */

#include <math.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#include "design2_common.h"

#ifdef SIM_WITH_UI
#include "sim_config.h"
#include "NaviArrow.h"
#include "vmap_config.h"
#include "vmap_view.h"
#endif

/* ── 色板（宣纸白 / 单一墨绿 / 更硬的灰阶）───────────────────────
 *
 * 对比上一轮：
 *   - 次要文字 #8B8781 → #6E6A63（约 58% 黑），最短 11px；
 *   - 发丝线 8~10% 黑 → #C9C5BD（约 22% 黑）；
 *   - 表盘轨道 12% 黑 → #C4BEB2（约 23% 黑），刻度 #8F8A7F（约 44% 黑）。
 * 这三处正是上一轮阳光档最先消失的元素。 */
#define E_BG      0xF7F5F0u   /**< 纸底 */
#define E_INK     0x141518u   /**< 主文字 */
#define E_MUTE    0x6E6A63u   /**< 次要文字（≈58% 黑） */
#define E_ACC     0x0B6E4Fu   /**< 唯一强调色（墨绿） */
#define E_TRACK   0xC4BEB2u   /**< 表盘整圈轨道（≈23% 黑） */
#define E_TICK    0x8F8A7Fu   /**< 刻度（≈44% 黑） */
#define E_HAIR    0xC9C5BDu   /**< 1px 分隔线（≈22% 黑） */
#define E_SECTOR  0xDCE9E2u   /**< 选中扇区浅填充 */
#define E_MAP     0xE9E6DFu   /**< 示意图纸（无 vmap 时） */
#define E_ROAD    0xFBF9F4u   /**< 示意道路 */
#define E_WHITE   0xFFFFFFu   /**< 地图上的提示条 */

#define E_INK_S   "141518"

/* ── 字号阶梯：全设计只有这 6 档（见 FONT_PLAN.md）──────────────── */
enum {
    E_PX_HERO  = 64,   /**< 骑行时速 */
    E_PX_TITLE = 30,   /**< 页标题 / 盘心模式名 / 转向距离 */
    E_PX_VALUE = 22,   /**< 关键数字 / 指标值 / 记录里程 */
    E_PX_BODY  = 15,   /**< 行名 / 日期 / 关于页值 */
    E_PX_SMALL = 12,   /**< 顶栏 / 描述 / 状态 / 单位说明 */
    E_PX_MICRO = 11,   /**< 图例 / 指标标签 / 单位（下限） */
};

/* ── 屏幕 ──────────────────────────────────────────────────────── */

enum {
    E_SCR_MAIN = 0,
    E_SCR_ROTATE,
    E_SCR_LONGPRESS,
    E_SCR_RIDE,
    E_SCR_NAV,
    E_SCR_RECORD,
    E_SCR_SETTINGS,
    E_SCR_DISPLAY,
    E_SCR_SENSOR,
    E_SCR_ABOUT,
    E_SCR_COUNT,
};

static const char *const e_screen_names[E_SCR_COUNT] = {
    "main", "rotate", "longpress", "ride", "nav",
    "record", "settings", "display", "sensor", "about",
};

/* ── 小工具 ────────────────────────────────────────────────────── */

static lv_obj_t *s_scr;
static int s_screen;

/**
 * @brief lv_line 的点数组池。
 *
 * LVGL 的 lv_line_set_points() 只存指针不拷贝；动态算出来的刻度/舵柄如果放
 * 栈上会立刻失效。这里给整屏一个固定池，重建时归零，避免每根线 malloc。
 */
#define E_PTS_MAX 192
static lv_point_precise_t s_pts[E_PTS_MAX][2];
static int s_pts_n;

static void e_pts_reset(void)
{
    s_pts_n = 0;
}

static const lv_point_precise_t *e_seg(int x1, int y1, int x2, int y2)
{
    if (s_pts_n >= E_PTS_MAX) {
        s_pts_n = 0;
    }
    lv_point_precise_t *p = s_pts[s_pts_n++];

    p[0].x = x1;
    p[0].y = y1;
    p[1].x = x2;
    p[1].y = y2;
    return p;
}

static lv_obj_t *e_lab(lv_obj_t *p, const char *txt, int px, uint32_t hex,
                       int x, int y)
{
    return d_label(p, txt, px, hex, x, y);
}

static lv_obj_t *e_lab_w(lv_obj_t *p, const char *txt, int px, uint32_t hex,
                         int x, int y, int w, lv_text_align_t align)
{
    return d_label_w(p, txt, px, hex, x, y, w, align);
}

/** 1px 分隔线：用已经压到 22% 黑的颜色，不再叠加透明度。 */
static void e_hair(lv_obj_t *p, int x, int y, int w)
{
    (void)d_hline(p, x, y, w, E_HAIR, LV_OPA_COVER);
}

static void e_top(lv_obj_t *p, const char *left, const char *right)
{
    e_lab(p, left, E_PX_SMALL, E_MUTE, 24, 13);
    e_lab_w(p, right, E_PX_SMALL, E_MUTE, 140, 13, 76, LV_TEXT_ALIGN_RIGHT);
}

/** 单位：贴着数值基线放，11px。 */
static void e_unit(lv_obj_t *row, const char *unit, int pad_bottom)
{
    lv_obj_t *u = lv_label_create(row);

    lv_label_set_text(u, unit);
    lv_obj_set_style_text_font(u, sim_font_cjk(E_PX_MICRO), 0);
    lv_obj_set_style_text_color(u, lv_color_hex(E_MUTE), 0);
    lv_obj_set_style_pad_bottom(u, pad_bottom, 0);
}

/** 数值 + 单位的一行（22px 值 + 11px 单位）。 */
static void e_value_row(lv_obj_t *p, int x, int y, int w, const char *value,
                        const char *unit, int px)
{
    lv_obj_t *row = d_stack(p, x, y, w, px + 6, LV_FLEX_ALIGN_CENTER, 3);
    lv_obj_t *v = lv_label_create(row);

    lv_label_set_text(v, value);
    lv_obj_set_style_text_font(v, sim_font_cjk(px), 0);
    lv_obj_set_style_text_color(v, lv_color_hex(E_INK), 0);
    if (unit && unit[0]) {
        e_unit(row, unit, px >= 22 ? 4 : 2);
    }
}

/** 圆弧（可关闭圆角端帽 = 扇区/仪表用；开 = 进度用）。 */
static lv_obj_t *e_arc(lv_obj_t *p, int cx, int cy, int d, int thickness,
                       int start, int span, uint32_t hex, bool rounded)
{
    lv_obj_t *arc = lv_arc_create(p);

    lv_obj_set_size(arc, d, d);
    lv_obj_set_pos(arc, cx - d / 2, cy - d / 2);
    lv_obj_remove_flag(arc, LV_OBJ_FLAG_CLICKABLE);
    lv_obj_remove_flag(arc, LV_OBJ_FLAG_SCROLLABLE);
    lv_obj_set_style_pad_all(arc, 0, 0);
    lv_obj_set_style_bg_opa(arc, LV_OPA_TRANSP, 0);
    lv_obj_set_style_border_width(arc, 0, 0);
    lv_obj_set_style_outline_width(arc, 0, 0);
    lv_obj_set_style_shadow_width(arc, 0, 0);

    lv_obj_set_style_arc_opa(arc, LV_OPA_TRANSP, LV_PART_MAIN);
    lv_obj_set_style_arc_width(arc, 0, LV_PART_MAIN);
    lv_obj_set_style_arc_rounded(arc, false, LV_PART_MAIN);

    lv_obj_set_style_arc_opa(arc, LV_OPA_COVER, LV_PART_INDICATOR);
    lv_obj_set_style_arc_width(arc, thickness, LV_PART_INDICATOR);
    lv_obj_set_style_arc_color(arc, lv_color_hex(hex), LV_PART_INDICATOR);
    lv_obj_set_style_arc_rounded(arc, rounded, LV_PART_INDICATOR);

    lv_obj_set_style_bg_opa(arc, LV_OPA_TRANSP, LV_PART_KNOB);
    lv_obj_set_style_border_width(arc, 0, LV_PART_KNOB);
    lv_obj_set_style_pad_all(arc, 0, LV_PART_KNOB);

    lv_arc_set_bg_angles(arc, start, start + span);
    lv_arc_set_rotation(arc, 0);
    lv_arc_set_range(arc, 0, 100);
    lv_arc_set_value(arc, 100);
    return arc;
}

/**
 * @brief 真径向刻度。
 *
 * design2_common 的 d2_tick() 用横/竖色块近似，斜刻度会变成水平短杠；
 * 舵轮要的是从圆心放射的线，所以这里直接 lv_line。
 */
static void e_tick(lv_obj_t *p, int cx, int cy, int deg, int r1, int r2,
                   int thickness, uint32_t hex)
{
    const double a = (double)deg * 3.14159265358979 / 180.0;
    const int x1 = cx + (int)lround(sin(a) * r1);
    const int y1 = cy - (int)lround(cos(a) * r1);
    const int x2 = cx + (int)lround(sin(a) * r2);
    const int y2 = cy - (int)lround(cos(a) * r2);

    (void)d2_poly(p, e_seg(x1, y1, x2, y2), 2, thickness, hex, true);
}

/** 舵柄：从轮毂边缘 r0 指向 r1，末端一根垂直于半径的短横。 */
static void e_tiller(lv_obj_t *p, int cx, int cy, int deg, int r0, int r1)
{
    const double a = (double)deg * 3.14159265358979 / 180.0;
    const double sx = sin(a);
    const double sy = -cos(a);
    const double px = cos(a);
    const double py = sin(a);
    const int x0 = cx + (int)lround(sx * r0);
    const int y0 = cy + (int)lround(sy * r0);
    const int x1 = cx + (int)lround(sx * r1);
    const int y1 = cy + (int)lround(sy * r1);

    (void)d2_poly(p, e_seg(x0, y0, x1, y1), 2, 3, E_INK, true);
    (void)d2_poly(p, e_seg(x1 - (int)lround(px * 8),
                           y1 - (int)lround(py * 8),
                           x1 + (int)lround(px * 8),
                           y1 + (int)lround(py * 8)),
                  2, 3, E_INK, true);
}

/** 盘心轮毂：纸色圆 + 1px 边，用来把舵柄和文字分开。 */
static void e_hub(lv_obj_t *p, int cx, int cy, int d)
{
    lv_obj_t *o = d_box(p, cx - d / 2, cy - d / 2, d, d, E_BG,
                        LV_OPA_COVER, d / 2);

    lv_obj_set_style_border_width(o, 1, 0);
    lv_obj_set_style_border_color(o, lv_color_hex(E_HAIR), 0);
    lv_obj_set_style_border_opa(o, LV_OPA_COVER, 0);
}

/**
 * @brief 舵轮盘面。
 *
 * @param sel_deg 选中扇区中心（从 12 点顺时针；-1 = 不画扇区）
 * @param ptr_deg 舵柄角度（从 12 点顺时针）
 */
static void e_dial(lv_obj_t *p, int cx, int cy, int sel_deg, int ptr_deg,
                   bool progress)
{
    /* 整圈轨道：2px，23% 黑。 */
    (void)d2_ring(p, cx, cy, 160, 2, E_TRACK);

    /* 选中扇区：24px 浅绿带 + 内外两条深绿边。 */
    if (sel_deg >= 0) {
        const int a = sel_deg - 90;   /* 转成 LVGL：0°=3 点 */

        (void)e_arc(p, cx, cy, 144, 24, a - 26, 52, E_SECTOR, false);
        (void)e_arc(p, cx, cy, 170, 2, a - 26, 52, E_ACC, false);
        (void)e_arc(p, cx, cy, 118, 2, a - 26, 52, E_ACC, false);
    }

    /* 24 格细刻度 + 4 根主刻度（0/90/180/270）。 */
    for (int i = 0; i < 24; i++) {
        const int deg = i * 15;
        const bool major = (i % 6 == 0);

        e_tick(p, cx, cy, deg, major ? 84 : 86, major ? 92 : 90,
               major ? 3 : 1, major ? E_INK : E_TICK);
    }

    /* 轮毂 + 舵柄。 */
    e_hub(p, cx, cy, 116);
    e_tiller(p, cx, cy, ptr_deg, 58, 84);

    /* 长按进度：轮毂外一圈 270° 弧，半满 50%。 */
    if (progress) {
        lv_obj_t *tr = e_arc(p, cx, cy, 128, 3, 135, 270, E_TRACK, true);
        lv_obj_t *pr = lv_arc_create(p);

        (void)tr;
        lv_obj_set_size(pr, 128, 128);
        lv_obj_set_pos(pr, cx - 64, cy - 64);
        lv_obj_remove_flag(pr, LV_OBJ_FLAG_CLICKABLE);
        lv_obj_remove_flag(pr, LV_OBJ_FLAG_SCROLLABLE);
        lv_obj_set_style_pad_all(pr, 0, 0);
        lv_obj_set_style_bg_opa(pr, LV_OPA_TRANSP, 0);
        lv_obj_set_style_border_width(pr, 0, 0);
        lv_obj_set_style_outline_width(pr, 0, 0);
        lv_obj_set_style_shadow_width(pr, 0, 0);
        lv_obj_set_style_arc_opa(pr, LV_OPA_TRANSP, LV_PART_MAIN);
        lv_obj_set_style_arc_width(pr, 0, LV_PART_MAIN);
        lv_obj_set_style_arc_opa(pr, LV_OPA_COVER, LV_PART_INDICATOR);
        lv_obj_set_style_arc_width(pr, 4, LV_PART_INDICATOR);
        lv_obj_set_style_arc_color(pr, lv_color_hex(E_ACC), LV_PART_INDICATOR);
        lv_obj_set_style_arc_rounded(pr, true, LV_PART_INDICATOR);
        lv_obj_set_style_bg_opa(pr, LV_OPA_TRANSP, LV_PART_KNOB);
        lv_obj_set_style_border_width(pr, 0, LV_PART_KNOB);
        lv_obj_set_style_pad_all(pr, 0, LV_PART_KNOB);
        lv_arc_set_bg_angles(pr, 135, 45);   /* 270°，从左下经上到右下 */
        lv_arc_set_rotation(pr, 0);
        lv_arc_set_range(pr, 0, 100);
        lv_arc_set_value(pr, 50);
    }
}

/** 四个模式名：12/3/6/9 点，选中 15px 黑、未选中 12px 灰。 */
static void e_mode_labels(lv_obj_t *p, int cx, int cy, int on)
{
    static const char *const names[4] = { "骑行", "导航", "记录", "设置" };
    static const int lx[4] = { 0, 1, 0, -1 };
    static const int ly[4] = { -1, 0, 1, 0 };

    for (int i = 0; i < 4; i++) {
        const bool sel = (i == on);
        const int px = sel ? E_PX_BODY : E_PX_SMALL;
        const int x = cx + lx[i] * 100 - 20;
        const int y = cy + ly[i] * 104 - (sel ? 10 : 8);

        e_lab_w(p, names[i], px, sel ? E_INK : E_MUTE, x, y, 40,
                LV_TEXT_ALIGN_CENTER);
    }
}

