static void e_main_common(int screen)
{
    const bool rotate = (screen == E_SCR_ROTATE);
    const bool press = (screen == E_SCR_LONGPRESS);
    const int on = rotate ? 1 : 0;
    const int ptr = rotate ? 45 : 0;
    const int sel = press ? -1 : (rotate ? 45 : 0);
    const e_mode_t *m = &e_modes[on];

    d_bg(s_scr, E_BG);

    if (rotate) {
        e_top(s_scr, "模式", "01 → 02");
    } else {
        e_top(s_scr, "模式", "01 / 04");
    }

    e_dial(s_scr, 120, 146, sel, ptr, press);
    e_mode_labels(s_scr, 120, 146, on);

    if (press) {
        /* 长按：模式名 / 描述 / 进度提示 / 50%，轮毂里不再放关键数字。 */
        lv_obj_t *name_stack = d_stack(s_scr, 40, 100, 160, 40,
                                       LV_FLEX_ALIGN_CENTER, 0);
        lv_obj_t *name = lv_label_create(name_stack);

        lv_label_set_text(name, m->name);
        lv_obj_set_style_text_font(name, sim_font_cjk(E_PX_TITLE), 0);
        lv_obj_set_style_text_color(name, lv_color_hex(E_INK), 0);
        e_lab_w(s_scr, m->desc, E_PX_SMALL, E_MUTE, 40, 140, 160,
                LV_TEXT_ALIGN_CENTER);
        e_lab_w(s_scr, "长按 1 进入", E_PX_SMALL, E_MUTE, 40, 160, 160,
                LV_TEXT_ALIGN_CENTER);
        e_lab_w(s_scr, "50%", E_PX_VALUE, E_ACC, 40, 182, 160,
                LV_TEXT_ALIGN_CENTER);
    } else {
        e_mode_center(s_scr, 120, 146, m, false);
    }

    d2_legend(s_scr, 270, E_PX_MICRO, E_MUTE,
              "短按 #" E_INK_S " 1# 旋转 · 长按 #" E_INK_S " 1# 进入");
    d2_legend(s_scr, 286, E_PX_MICRO, E_MUTE,
              "短按 #" E_INK_S " 2# 上一项 · 长按 #" E_INK_S " 2# 开始");
}

static void e_main(lv_obj_t *scr)
{
    (void)scr;
    e_main_common(E_SCR_MAIN);
}

