/* ── 场景入口（十屏）───────────────────────────────────────────── */

static void e_build(lv_obj_t *scr, int screen)
{
    switch (screen) {
        case E_SCR_ROTATE:    e_rotate(scr); break;
        case E_SCR_LONGPRESS: e_longpress(scr); break;
        case E_SCR_RIDE:      e_ride(scr); break;
        case E_SCR_NAV:       e_nav(scr); break;
        case E_SCR_RECORD:    e_record(scr); break;
        case E_SCR_SETTINGS:  e_settings(scr); break;
        case E_SCR_DISPLAY:   e_display(scr); break;
        case E_SCR_SENSOR:    e_sensor(scr); break;
        case E_SCR_ABOUT:     e_about(scr); break;
        default:              e_main(scr); break;
    }
}

static int e_count_objs(lv_obj_t *o)
{
    int n = 1;
    const uint32_t c = lv_obj_get_child_count(o);

    for (uint32_t i = 0; i < c; i++) {
        n += e_count_objs(lv_obj_get_child(o, (int32_t)i));
    }
    return n;
}

static void e_rebuild(int screen)
{
    if (screen < 0 || screen >= E_SCR_COUNT) {
        screen = E_SCR_MAIN;
    }
#ifdef SIM_WITH_UI
    e_vmap_stop();   /* 必须在 lv_obj_clean 之前释放瓦片/画布 */
#endif
    lv_obj_clean(s_scr);
    e_pts_reset();
    s_screen = screen;
    e_build(s_scr, screen);
    printf("design3: screen=%s objects=%d\n", e_screen_names[screen],
           e_count_objs(s_scr));
    fflush(stdout);
}

static int e_screen_from_env(void)
{
    const char *s = getenv("SIM_DESIGN_SCREEN");

    if (s == NULL || s[0] == '\0') {
        return E_SCR_MAIN;
    }
    for (int i = 0; i < E_SCR_COUNT; i++) {
        if (strcmp(s, e_screen_names[i]) == 0) {
            return i;
        }
    }
    /* 上一轮的四屏名保持可用。 */
    if (strcmp(s, "menu") == 0) {
        return E_SCR_SETTINGS;
    }
    if (s[0] >= '0' && s[0] <= '9' && s[1] == '\0') {
        return s[0] - '0';
    }
    fprintf(stderr,
            "sim: unknown SIM_DESIGN_SCREEN=%s "
            "(main|rotate|longpress|ride|nav|record|settings|display|sensor|about)\n",
            s);
    return E_SCR_MAIN;
}

static void e_key_timer(lv_timer_t *t)
{
    (void)t;
    for (;;) {
        int k = sim_display_take_raw_key();

        if (k == 0) {
            break;
        }
        if (k >= '1' && k <= '9') {
            e_rebuild(k - '1');
        } else if (k == '0') {
            e_rebuild(E_SCR_COUNT - 1);
        }
    }
}

void scene_design_e_create(lv_obj_t *scr, const sim_cfg_t *cfg)
{
    (void)cfg;
    s_scr = scr;
    e_rebuild(e_screen_from_env());
    lv_timer_create(e_key_timer, 60, NULL);
}
